<?php require __DIR__.'/_head.php';$id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT * FROM orders WHERE id=?');$s->execute([$id]);$o=$s->fetch();if(!$o){echo '<p>অর্ডার পাওয়া যায়নি</p>';require __DIR__.'/_foot.php';exit;}$s=$pdo->prepare('SELECT * FROM order_items WHERE order_id=?');$s->execute([$id]);$items=$s->fetchAll();?>
<div class="card"><h2>অর্ডার #<?=$id?></h2><p>নাম: <?=e($o['customer_name'])?> | ফোন: <?=e($o['phone'])?></p><p>ঠিকানা: <?=e($o['address'])?></p><p>ডেলিভারি চার্জ: <?=money($o['delivery_fee'])?></p><p>নোট: <?=e($o['note'])?></p><table><tr><th>পণ্য</th><th>পরিমাণ</th><th>একক দাম</th></tr><?php foreach($items as $i):?><tr><td><?=e($i['product_name'])?></td><td><?=$i['quantity']?></td><td><?=$i['unit_price']===null?'পরে নিশ্চিত':money($i['unit_price'])?></td></tr><?php endforeach;?></table></div><?php require __DIR__.'/_foot.php';?>
